class Message(object):
    def __init__(self, message: str, sender: int, receiver: int) -> None:
        self.message = message
        self.sender = sender
        self.receiver = receiver

    def __str__(self) -> str:
        return self.message

    def __eq__(self, o: object) -> bool:
        if not isinstance(o, Message):
            return NotImplemented
        return self.message == o.message

    def __hash__(self) -> int:
        return hash(self.message)

class Message {
    String message;
    int sender, receiver;

    Message(String m, int s, int r) {
        this.message = m;
        this.sender = s;
        this.receiver = r;
    }

    @Override public String toString() { return message; }

    @Override public boolean equals(Object o) {
        if (!(o instanceof Message)) return false;
        return message.equals(((Message) o).message);
    }

    @Override public int hashCode() { return message.hashCode(); }
}

